# Disable Fullscreen Optimizations Write-Host "Disabling fullscreen optimizations globally..." -ForegroundColor Cyan # Disable fullscreen optimizations system-wide Set-ItemProperty -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_Enabled" -Value 0 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_FSEBehaviorMode" -Value 2 -Type DWord -Force -ErrorAction Stop Set-ItemProperty -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_HonorUserFSEBehaviorMode" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Set-ItemProperty -Path "HKCU:\System\GameConfigStore" -Name "GameDVR_DXGIHonorFSEWindowsCompatible" -Value 1 -Type DWord -Force -ErrorAction SilentlyContinue Write-Host "Fullscreen optimizations have been disabled." -ForegroundColor Green Write-Host "Games will now use exclusive fullscreen mode for better performance." -ForegroundColor Gray